import React, { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Modal,
  Pressable,
  ScrollView,
  Text,
  TextInput,
  View,
} from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import * as Clipboard from 'expo-clipboard';
import { useAuthStore } from '../stores/authStore';
import {
  createStudySession,
  endStudySession,
  fetchStudySessions,
  getStudySession,
  joinStudySession,
  leaveStudySession,
} from '../services/api';
import { Button } from './ui';

interface StudySessionModalProps {
  visible: boolean;
  onClose: () => void;
  deckId: string;
  autoJoinCode?: string;
}

type SessionRow = {
  id: string;
  startedAt?: string;
  isActive?: boolean;
  createdBy?: string;
};

export default function StudySessionModal({
  visible,
  onClose,
  deckId,
  autoJoinCode,
}: StudySessionModalProps) {
  const user = useAuthStore(s => s.user);
  const [sessions, setSessions] = useState<SessionRow[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [joinCode, setJoinCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);

  const loadSessions = useCallback(async () => {
    if (!deckId) return;
    setLoading(true);
    try {
      const data = await fetchStudySessions(deckId);
      setSessions((data as SessionRow[]) || []);
    } catch {
      setSessions([]);
    } finally {
      setLoading(false);
    }
  }, [deckId]);

  useEffect(() => {
    if (!visible) return;
    void loadSessions();
  }, [visible, loadSessions]);

  useEffect(() => {
    if (!visible || !autoJoinCode || !user?.id) return;
    setJoinCode(autoJoinCode);
    void (async () => {
      setBusy(true);
      try {
        await joinStudySession(autoJoinCode, user.id);
        setActiveSessionId(autoJoinCode);
        await getStudySession(autoJoinCode);
        await loadSessions();
      } catch {
        Alert.alert('Join failed', 'Could not join session. Check the code and try again.');
      } finally {
        setBusy(false);
      }
    })();
  }, [visible, autoJoinCode, user?.id]);

  const handleCreate = async () => {
    if (!user?.id) return;
    setBusy(true);
    try {
      const session = (await createStudySession({ deckId, userId: user.id })) as SessionRow;
      setActiveSessionId(session.id);
      await loadSessions();
    } catch {
      Alert.alert('Error', 'Failed to create study session.');
    } finally {
      setBusy(false);
    }
  };

  const handleJoin = async (sessionId: string) => {
    if (!user?.id) return;
    setBusy(true);
    try {
      await joinStudySession(sessionId, user.id);
      setActiveSessionId(sessionId);
      await loadSessions();
    } catch {
      Alert.alert('Error', 'Failed to join session.');
    } finally {
      setBusy(false);
    }
  };

  const handleJoinByCode = async () => {
    const code = joinCode.trim();
    if (!code) return;
    await handleJoin(code);
  };

  const handleLeave = async () => {
    if (!activeSessionId || !user?.id) return;
    setBusy(true);
    try {
      await leaveStudySession(activeSessionId, user.id);
      setActiveSessionId(null);
      await loadSessions();
    } catch {
      Alert.alert('Error', 'Failed to leave session.');
    } finally {
      setBusy(false);
    }
  };

  const handleEnd = async () => {
    if (!activeSessionId) return;
    setBusy(true);
    try {
      await endStudySession(activeSessionId);
      setActiveSessionId(null);
      await loadSessions();
    } catch {
      Alert.alert('Error', 'Failed to end session.');
    } finally {
      setBusy(false);
    }
  };

  const copyCode = async (code: string) => {
    await Clipboard.setStringAsync(code);
    Alert.alert('Copied', 'Session code copied to clipboard.');
  };

  return (
    <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}>
      <View className="flex-1 bg-black/50 justify-end">
        <View className="bg-white dark:bg-slate-800 rounded-t-3xl max-h-[85%]">
          <View className="flex-row items-center justify-between px-4 py-4 border-b border-slate-200 dark:border-slate-700">
            <View className="flex-row items-center gap-2">
              <Ionicons name="people" size={20} color="#6366f1" />
              <Text className="text-lg font-semibold text-slate-900 dark:text-slate-100">
                Study together
              </Text>
            </View>
            <Pressable onPress={onClose} className="p-2">
              <Ionicons name="close" size={22} color="#94a3b8" />
            </Pressable>
          </View>

          <ScrollView contentContainerClassName="p-4 pb-8">
            <Text className="text-sm text-slate-500 dark:text-slate-400 mb-3">
              Create or join a shared study session for this deck.
            </Text>

            <Button className="mb-4" loading={busy} onPress={() => void handleCreate()}>
              Create session
            </Button>

            <View className="flex-row gap-2 mb-4">
              <TextInput
                value={joinCode}
                onChangeText={setJoinCode}
                placeholder="Session code"
                placeholderTextColor="#94a3b8"
                className="flex-1 border border-slate-200 dark:border-slate-600 rounded-xl px-3 py-2 text-slate-900 dark:text-slate-100 bg-slate-50 dark:bg-slate-900"
              />
              <Button size="sm" loading={busy} disabled={!joinCode.trim()} onPress={() => void handleJoinByCode()}>
                Join
              </Button>
            </View>

            {activeSessionId ? (
              <View className="mb-4 p-3 rounded-xl bg-indigo-50 dark:bg-indigo-950/40 border border-indigo-200 dark:border-indigo-800">
                <Text className="text-sm font-semibold text-indigo-900 dark:text-indigo-100 mb-1">
                  Active session
                </Text>
                <Text className="text-xs text-indigo-700 dark:text-indigo-300 font-mono mb-2">
                  {activeSessionId.slice(0, 8)}
                </Text>
                <View className="flex-row gap-2">
                  <Button size="sm" variant="secondary" onPress={() => void copyCode(activeSessionId)}>
                    Copy code
                  </Button>
                  <Button size="sm" variant="secondary" onPress={() => void handleLeave()}>
                    Leave
                  </Button>
                  <Button size="sm" variant="danger" onPress={() => void handleEnd()}>
                    End
                  </Button>
                </View>
              </View>
            ) : null}

            {loading ? (
              <ActivityIndicator color="#6366f1" className="py-6" />
            ) : sessions.length === 0 ? (
              <Text className="text-sm text-slate-500 text-center py-4">No active sessions yet.</Text>
            ) : (
              sessions.map(session => (
                <View
                  key={session.id}
                  className="mb-2 p-3 rounded-xl border border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-900"
                >
                  <Text className="text-sm font-medium text-slate-800 dark:text-slate-100">
                    Session {session.id.slice(0, 8)}
                  </Text>
                  <Text className="text-xs text-slate-500 mt-0.5">
                    {session.isActive ? 'Active' : 'Ended'}
                  </Text>
                  <Button
                    size="sm"
                    className="mt-2 self-start"
                    loading={busy}
                    onPress={() => void handleJoin(session.id)}
                  >
                    Join
                  </Button>
                </View>
              ))
            )}
          </ScrollView>
        </View>
      </View>
    </Modal>
  );
}
