const IMMERSIVE_SCREENS = new Set([
  'FlashcardReview',
  'CramSession',
  'MatchStudy',
  'LearnStudy',
  'TestTaking',
  'TestResults',
  'GameScreen',
  'GameResult',
]);

export function shouldHideTabBar(routeName: string | undefined): boolean {
  if (!routeName) return false;
  return IMMERSIVE_SCREENS.has(routeName);
}
