import { Platform } from 'react-native';
import Constants from 'expo-constants';
import { API_BASE_URL, getAuthHeaders } from './supabase';

export function isPushNotificationsSupported(): boolean {
  return true;
}

export async function registerForPushNotifications(): Promise<string | null> {
  const Notifications = await import('expo-notifications');

  Notifications.setNotificationHandler({
    handleNotification: async () => ({
      shouldShowAlert: true,
      shouldPlaySound: false,
      shouldSetBadge: true,
      shouldShowBanner: true,
      shouldShowList: true,
    }),
  });

  const { status: existing } = await Notifications.getPermissionsAsync();
  let finalStatus = existing;
  if (existing !== 'granted') {
    const { status } = await Notifications.requestPermissionsAsync();
    finalStatus = status;
  }
  if (finalStatus !== 'granted') return null;

  const projectId = Constants.expoConfig?.extra?.eas?.projectId as string | undefined;
  try {
    const token = await Notifications.getExpoPushTokenAsync(projectId ? { projectId } : undefined);
    if (Platform.OS === 'android') {
      await Notifications.setNotificationChannelAsync('default', {
        name: 'default',
        importance: Notifications.AndroidImportance.DEFAULT,
      });
    }
    return token.data;
  } catch {
    return null;
  }
}

export async function uploadPushToken(expoPushToken: string): Promise<void> {
  try {
    const headers = await getAuthHeaders();
    await fetch(`${API_BASE_URL}/api/v1/users/push-token`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', ...headers },
      body: JSON.stringify({ token: expoPushToken }),
    });
  } catch (e) {
    console.warn('[pushNotifications] Failed to upload push token:', e);
  }
}

export function addNotificationResponseListener(
  handler: (url: string | undefined) => void
): () => void {
  let unsubscribe: (() => void) | undefined;

  void import('expo-notifications').then(Notifications => {
    Notifications.setNotificationHandler({
      handleNotification: async () => ({
        shouldShowAlert: true,
        shouldPlaySound: false,
        shouldSetBadge: true,
        shouldShowBanner: true,
        shouldShowList: true,
      }),
    });
    const sub = Notifications.addNotificationResponseReceivedListener(response => {
      const url = response.notification.request.content.data?.url as string | undefined;
      handler(url);
    });
    unsubscribe = () => sub.remove();
  });

  return () => {
    unsubscribe?.();
  };
}
