// ===========================================
// Lantern Study Mobile - Challenge Modal
// Send a real duel challenge to a group member
// ===========================================

import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Modal,
  TouchableOpacity,
  ActivityIndicator,
  ScrollView,
  Alert,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { useTheme } from '../theme';
import { useGameStore, GameUser, GameConfig } from '../stores';
import { useAuthStore } from '../stores/authStore';

interface ChallengeModalProps {
  visible: boolean;
  onClose: () => void;
  opponent: GameUser;
  onChallengeSent?: () => void;
  onSoloStart?: () => void;
  groupId?: string;
}

const QUESTION_COUNT_OPTIONS = [5, 10, 15, 20];

export default function ChallengeModal({
  visible,
  onClose,
  opponent,
  onChallengeSent,
  onSoloStart,
  groupId,
}: ChallengeModalProps) {
  const { colors } = useTheme();
  const { user } = useAuthStore();
  const { sendChallenge, startSoloPractice, isLoading, error } = useGameStore();

  const [questionCount, setQuestionCount] = useState(10);

  const currentUser: GameUser | null = user
    ? {
        id: user.id,
        name:
          user.user_metadata?.full_name ||
          user.user_metadata?.name ||
          user.email?.split('@')[0] ||
          'You',
        avatarUrl: user.user_metadata?.avatar_url,
      }
    : null;

  const config: GameConfig = {
    questionCount,
    groupId,
  };

  const handleSendChallenge = async () => {
    if (!currentUser) return;
    try {
      await sendChallenge(config, currentUser, opponent);
      Alert.alert(
        'Challenge Sent',
        `${opponent.name} will be notified and can accept or decline your duel.`
      );
      onChallengeSent?.();
      onClose();
    } catch (err) {
      console.error('Failed to send challenge:', err);
    }
  };

  const handleSoloPractice = async () => {
    if (!currentUser) return;
    try {
      await startSoloPractice(config, currentUser);
      onSoloStart?.();
      onClose();
    } catch (err) {
      console.error('Failed to start solo practice:', err);
    }
  };

  const styles = StyleSheet.create({
    overlay: {
      flex: 1,
      backgroundColor: 'rgba(0, 0, 0, 0.5)',
      justifyContent: 'flex-end',
    },
    container: {
      backgroundColor: colors.card,
      borderTopLeftRadius: 20,
      borderTopRightRadius: 20,
      maxHeight: '85%',
    },
    header: {
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'space-between',
      padding: 16,
      borderBottomWidth: 1,
      borderBottomColor: colors.border,
    },
    title: {
      fontSize: 18,
      fontWeight: '700',
      color: colors.text,
    },
    content: {
      padding: 16,
    },
    vsRow: {
      flexDirection: 'row',
      alignItems: 'center',
      justifyContent: 'center',
      marginVertical: 16,
      gap: 12,
    },
    playerName: {
      fontSize: 16,
      fontWeight: '600',
      color: colors.text,
    },
    vsText: {
      fontSize: 14,
      fontWeight: '800',
      color: '#ef4444',
    },
    sectionTitle: {
      fontSize: 14,
      fontWeight: '600',
      color: colors.textSecondary,
      marginBottom: 8,
      marginTop: 8,
    },
    optionRow: {
      flexDirection: 'row',
      flexWrap: 'wrap',
      gap: 8,
    },
    optionChip: {
      paddingHorizontal: 16,
      paddingVertical: 8,
      borderRadius: 20,
      borderWidth: 1,
      borderColor: colors.border,
    },
    optionChipSelected: {
      backgroundColor: colors.primary,
      borderColor: colors.primary,
    },
    optionText: {
      fontSize: 14,
      color: colors.text,
    },
    optionTextSelected: {
      color: '#FFFFFF',
      fontWeight: '600',
    },
    primaryButton: {
      backgroundColor: '#ef4444',
      paddingVertical: 14,
      borderRadius: 12,
      alignItems: 'center',
      marginTop: 20,
    },
    secondaryButton: {
      backgroundColor: colors.background,
      paddingVertical: 14,
      borderRadius: 12,
      alignItems: 'center',
      marginTop: 10,
      borderWidth: 1,
      borderColor: colors.border,
    },
    buttonText: {
      color: '#FFFFFF',
      fontSize: 16,
      fontWeight: '700',
    },
    secondaryButtonText: {
      color: colors.text,
      fontSize: 16,
      fontWeight: '600',
    },
    errorText: {
      color: '#ef4444',
      fontSize: 13,
      marginTop: 8,
      textAlign: 'center',
    },
    hint: {
      fontSize: 13,
      color: colors.textSecondary,
      textAlign: 'center',
      marginTop: 12,
      lineHeight: 18,
    },
  });

  return (
    <Modal visible={visible} animationType="slide" transparent onRequestClose={onClose}>
      <View style={styles.overlay}>
        <SafeAreaView style={styles.container} edges={['bottom']}>
          <View style={styles.header}>
            <Text style={styles.title}>Challenge to a Duel</Text>
            <TouchableOpacity onPress={onClose}>
              <Ionicons name="close" size={24} color={colors.textSecondary} />
            </TouchableOpacity>
          </View>

          <ScrollView style={styles.content}>
            <View style={styles.vsRow}>
              <Text style={styles.playerName}>You</Text>
              <Text style={styles.vsText}>VS</Text>
              <Text style={styles.playerName}>{opponent.name}</Text>
            </View>

            <Text style={styles.sectionTitle}>Number of Questions</Text>
            <View style={styles.optionRow}>
              {QUESTION_COUNT_OPTIONS.map(count => (
                <TouchableOpacity
                  key={count}
                  style={[styles.optionChip, questionCount === count && styles.optionChipSelected]}
                  onPress={() => setQuestionCount(count)}
                >
                  <Text
                    style={[
                      styles.optionText,
                      questionCount === count && styles.optionTextSelected,
                    ]}
                  >
                    {count}
                  </Text>
                </TouchableOpacity>
              ))}
            </View>

            <Text style={styles.hint}>
              Your opponent will receive a notification and must accept before either of you can play the same question set.
            </Text>

            {error ? <Text style={styles.errorText}>{error}</Text> : null}

            <TouchableOpacity
              style={styles.primaryButton}
              onPress={handleSendChallenge}
              disabled={isLoading}
            >
              {isLoading ? (
                <ActivityIndicator color="#FFFFFF" />
              ) : (
                <Text style={styles.buttonText}>Send Challenge</Text>
              )}
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.secondaryButton}
              onPress={handleSoloPractice}
              disabled={isLoading}
            >
              <Text style={styles.secondaryButtonText}>Solo Practice Instead</Text>
            </TouchableOpacity>
          </ScrollView>
        </SafeAreaView>
      </View>
    </Modal>
  );
}
