import React, { useMemo } from 'react';
import { View, Text, ScrollView } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { useNavigation } from '@react-navigation/native';
import { useBudgetStore, formatCurrency } from '../../stores/budgetStore';
import { ScreenHeader, Card } from '../../components/ui';

export default function FinancialToolkitScreen() {
  const navigation = useNavigation<any>();
  const { transactions, monthlyExpenses, monthlyIncome, budgetProgress, expensesByCategory } = useBudgetStore();

  const avgDailySpend = useMemo(() => {
    const day = new Date().getDate();
    return day > 0 ? monthlyExpenses / day : 0;
  }, [monthlyExpenses]);

  const projectedMonth = useMemo(() => avgDailySpend * 30, [avgDailySpend]);

  return (
    <SafeAreaView className="flex-1 bg-slate-50 dark:bg-slate-900" edges={['top']}>
      <ScreenHeader title="Financial toolkit" onBack={() => navigation.goBack()} subtitle="Insights & projections" />
      <ScrollView contentContainerClassName="px-4 pb-8 gap-3">
        <View className="flex-row gap-3">
          <Card className="flex-1 items-center py-4">
            <Text className="text-xs text-slate-500">Income</Text>
            <Text className="text-lg font-bold text-emerald-600">{formatCurrency(monthlyIncome)}</Text>
          </Card>
          <Card className="flex-1 items-center py-4">
            <Text className="text-xs text-slate-500">Expenses</Text>
            <Text className="text-lg font-bold text-red-500">{formatCurrency(monthlyExpenses)}</Text>
          </Card>
        </View>
        <Card className="p-4">
          <Text className="font-semibold text-slate-900 dark:text-white mb-2">This month</Text>
          <Text className="text-sm text-slate-600 dark:text-slate-400">Budget used: {Math.round(budgetProgress * 100)}%</Text>
          <Text className="text-sm text-slate-600 dark:text-slate-400 mt-1">Avg daily spend: {formatCurrency(avgDailySpend)}</Text>
          <Text className="text-sm text-slate-600 dark:text-slate-400 mt-1">Projected month-end: {formatCurrency(projectedMonth)}</Text>
          <Text className="text-sm text-slate-600 dark:text-slate-400 mt-1">{transactions.length} transactions tracked</Text>
        </Card>
        <Card className="p-4">
          <Text className="font-semibold text-slate-900 dark:text-white mb-3">Top categories</Text>
          {expensesByCategory.slice(0, 5).map(c => (
            <View key={c.name} className="flex-row justify-between py-1.5 border-b border-slate-100 dark:border-slate-700">
              <Text className="text-sm text-slate-700 dark:text-slate-300">{c.name}</Text>
              <Text className="text-sm font-medium text-slate-900 dark:text-white">{formatCurrency(c.amount)}</Text>
            </View>
          ))}
          {expensesByCategory.length === 0 ? (
            <Text className="text-sm text-slate-500">No spending data yet.</Text>
          ) : null}
        </Card>
      </ScrollView>
    </SafeAreaView>
  );
}
