import React from 'react';
import { View, Text, Pressable } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { Badge } from '../ui';

export type TabKey = 'Home' | 'Study' | 'Chat' | 'Market' | 'More';

interface TabDef {
  key: TabKey;
  label: string;
  icon: keyof typeof Ionicons.glyphMap;
  activeIcon: keyof typeof Ionicons.glyphMap;
  badge?: number;
}

interface Props {
  activeTab: TabKey;
  onTabPress: (tab: TabKey) => void;
  dueCardsCount?: number;
  unreadChatCount?: number;
  unreadNotificationCount?: number;
  isMoreActive?: boolean;
}

export function BottomTabBar({
  activeTab,
  onTabPress,
  dueCardsCount = 0,
  unreadChatCount = 0,
  unreadNotificationCount = 0,
  isMoreActive,
}: Props) {
  const tabs: TabDef[] = [
    { key: 'Home', label: 'Home', icon: 'home-outline', activeIcon: 'home' },
    {
      key: 'Study',
      label: 'Study',
      icon: 'school-outline',
      activeIcon: 'school',
      badge: dueCardsCount,
    },
    {
      key: 'Chat',
      label: 'Chat',
      icon: 'chatbubbles-outline',
      activeIcon: 'chatbubbles',
      badge: unreadChatCount,
    },
    { key: 'Market', label: 'Market', icon: 'bag-outline', activeIcon: 'bag' },
    {
      key: 'More',
      label: 'More',
      icon: 'ellipsis-horizontal-outline',
      activeIcon: 'ellipsis-horizontal',
      badge: unreadNotificationCount,
    },
  ];

  return (
    <View className="absolute bottom-0 left-0 right-0 bg-white dark:bg-slate-800 border-t border-slate-200 dark:border-slate-700 pb-6 pt-2 px-2 flex-row">
      {tabs.map(tab => {
        const active = tab.key === 'More' ? isMoreActive : activeTab === tab.key;
        return (
          <Pressable
            key={tab.key}
            onPress={() => onTabPress(tab.key)}
            className="flex-1 items-center py-1"
          >
            <View className="relative">
              <Ionicons
                name={active ? tab.activeIcon : tab.icon}
                size={22}
                color={active ? '#6366f1' : '#94a3b8'}
              />
              {tab.badge ? <Badge count={tab.badge} /> : null}
            </View>
            <Text
              className={`text-[10px] mt-1 font-medium ${active ? 'text-indigo-500' : 'text-slate-400'}`}
            >
              {tab.label}
            </Text>
          </Pressable>
        );
      })}
    </View>
  );
}
