import React, { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  FlatList,
  Pressable,
  RefreshControl,
  Text,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import { useAuthStore, useMarketplaceStore } from '../../stores';
import { fetchMyInquiries, fetchMarketplaceListing } from '../../services/api';
import { ListingImage, timeAgo } from './marketplaceHelpers';

type InquiryItem = {
  id: string;
  listing_id: string;
  initial_message: string;
  status: string;
  created_at: string;
  listingTitle?: string;
  listingImage?: string;
};

type NavigationProp = {
  goBack: () => void;
  navigate: (screen: string, params?: Record<string, unknown>) => void;
};

async function enrichInquiries(raw: Awaited<ReturnType<typeof fetchMyInquiries>>): Promise<InquiryItem[]> {
  const listingCache = new Map<string, { title: string; image?: string }>();

  const enriched = await Promise.all(
    raw.map(async item => {
      let meta = listingCache.get(item.listing_id);
      if (!meta) {
        try {
          const listing = await fetchMarketplaceListing(item.listing_id);
          meta = { title: listing.title, image: listing.images?.[0] };
          listingCache.set(item.listing_id, meta);
        } catch {
          meta = { title: 'Listing unavailable' };
        }
      }
      return {
        id: item.id,
        listing_id: item.listing_id,
        initial_message: item.initial_message,
        status: item.status,
        created_at: item.created_at,
        listingTitle: meta.title,
        listingImage: meta.image,
      };
    })
  );

  return enriched.sort(
    (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
  );
}

export function InquiriesScreen({ navigation }: { navigation: NavigationProp }) {
  const { user } = useAuthStore();
  const { fetchInquiries } = useMarketplaceStore();
  const [inquiries, setInquiries] = useState<InquiryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchMyInquiries('seller');
      setInquiries(await enrichInquiries(data));
    } catch {
      if (user?.id) await fetchInquiries(user.id);
      const storeInquiries = useMarketplaceStore.getState().inquiries;
      setInquiries(
        storeInquiries.map(i => ({
          id: i.id,
          listing_id: i.listing_id,
          initial_message: i.message,
          status: 'open',
          created_at: i.created_at,
          listingTitle: i.listing?.title,
          listingImage: i.listing?.images?.[0],
        }))
      );
    } finally {
      setLoading(false);
    }
  }, [fetchInquiries, user?.id]);

  useEffect(() => {
    void load();
  }, [load]);

  const onRefresh = async () => {
    setRefreshing(true);
    await load();
    setRefreshing(false);
  };

  const statusColor = (status: string) => {
    switch (status) {
      case 'open':
        return 'bg-blue-100 text-blue-700 dark:bg-blue-900/40 dark:text-blue-300';
      case 'negotiating':
        return 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300';
      case 'purchased':
        return 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300';
      default:
        return 'bg-slate-100 text-slate-600 dark:bg-slate-700 dark:text-slate-300';
    }
  };

  return (
    <SafeAreaView className="flex-1 bg-slate-50 dark:bg-slate-900" edges={['top']}>
      <View className="px-4 pt-2 pb-3 flex-row items-center">
        <Pressable onPress={() => navigation.goBack()} className="p-2 -ml-2 mr-1">
          <Ionicons name="arrow-back" size={22} color="#64748b" />
        </Pressable>
        <Text className="text-xl font-bold text-slate-900 dark:text-slate-100">Inquiries</Text>
      </View>

      {loading && !inquiries.length ? (
        <View className="flex-1 items-center justify-center">
          <ActivityIndicator size="large" color="#6366f1" />
        </View>
      ) : (
        <FlatList
          data={inquiries}
          keyExtractor={item => item.id}
          contentContainerStyle={{ padding: 16, paddingBottom: 32 }}
          refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} tintColor="#6366f1" />}
          ListEmptyComponent={
            <View className="items-center py-16 px-6">
              <Ionicons name="chatbubbles-outline" size={48} color="#cbd5e1" />
              <Text className="text-lg font-semibold text-slate-800 dark:text-slate-200 mt-4">No inquiries yet</Text>
              <Text className="text-sm text-slate-500 dark:text-slate-400 text-center mt-2">
                When buyers message you about your listings, they will appear here.
              </Text>
            </View>
          }
          renderItem={({ item }) => (
            <Pressable
              onPress={() => navigation.navigate('ListingDetail', { listingId: item.listing_id })}
              className="flex-row bg-white dark:bg-slate-800 rounded-2xl border border-slate-200 dark:border-slate-700 overflow-hidden mb-3"
            >
              <View className="w-24 h-24">
                <ListingImage uri={item.listingImage} className="w-full h-full" />
              </View>
              <View className="flex-1 p-3">
                <View className="flex-row items-center justify-between gap-2">
                  <Text className="text-sm font-semibold text-slate-800 dark:text-slate-100 flex-1" numberOfLines={1}>
                    {item.listingTitle}
                  </Text>
                  <View className={`px-2 py-0.5 rounded-full ${statusColor(item.status)}`}>
                    <Text className="text-[10px] font-medium capitalize">{item.status}</Text>
                  </View>
                </View>
                <Text className="text-sm text-slate-600 dark:text-slate-300 mt-2" numberOfLines={2}>
                  {item.initial_message}
                </Text>
                <Text className="text-xs text-slate-400 mt-2">{timeAgo(item.created_at)}</Text>
              </View>
              <View className="justify-center pr-3">
                <Ionicons name="chevron-forward" size={18} color="#94a3b8" />
              </View>
            </Pressable>
          )}
        />
      )}
    </SafeAreaView>
  );
}
