import React, { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Pressable,
  ScrollView,
  Switch,
  Text,
  TextInput,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import type { NativeStackScreenProps } from '@react-navigation/native-stack';
import { useAuthStore } from '../../stores';
import { useGroupStore, type GroupPermissions } from '../../stores/groupStore';
import * as api from '../../services/api';
import { Button, ScreenHeader, Avatar } from '../../components/ui';
import type { ChatStackParamList } from '../../navigation/types';

type Props = NativeStackScreenProps<ChatStackParamList, 'CreateGroup'>;

interface SearchResult {
  id: string;
  username?: string | null;
  first_name?: string | null;
  last_name?: string | null;
  name: string;
  avatar_url?: string | null;
}

const DEFAULT_PERMISSIONS: GroupPermissions = {
  canSendMessages: true,
  canAddMembers: true,
  canEditSettings: false,
  canApproveMembers: false,
};

function PermissionToggle({
  label,
  enabled,
  onChange,
}: {
  label: string;
  enabled: boolean;
  onChange: (value: boolean) => void;
}) {
  return (
    <View className="flex-row items-center justify-between py-3 border-b border-slate-100 dark:border-slate-700">
      <Text className="text-sm font-medium text-slate-700 dark:text-slate-300 flex-1 pr-3">{label}</Text>
      <Switch value={enabled} onValueChange={onChange} trackColor={{ true: '#6366f1' }} />
    </View>
  );
}

export function CreateGroupScreen({ navigation, route }: Props) {
  const user = useAuthStore(s => s.user);
  const createGroup = useGroupStore(s => s.createGroup);
  const parentId = route.params?.parentId;
  const parentName = route.params?.parentName;
  const isSubGroup = !!parentId;

  const [step, setStep] = useState<'select_members' | 'group_details'>('select_members');
  const [selectedUsers, setSelectedUsers] = useState<SearchResult[]>([]);
  const [groupName, setGroupName] = useState('');
  const [groupDescription, setGroupDescription] = useState('');
  const [permissions, setPermissions] = useState<GroupPermissions>(DEFAULT_PERMISSIONS);
  const [searchTerm, setSearchTerm] = useState('');
  const [searchResults, setSearchResults] = useState<SearchResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [isCreating, setIsCreating] = useState(false);

  const selectedUserIds = selectedUsers.map(u => u.id);

  useEffect(() => {
    if (!searchTerm.trim() || searchTerm.trim().length < 2) {
      setSearchResults([]);
      return;
    }

    setIsSearching(true);
    const timeoutId = setTimeout(async () => {
      try {
        const data = await api.searchUsers(searchTerm.trim(), 20);
        const filtered = (data || [])
          .map((u): SearchResult => ({
            id: u.id,
            name: u.name,
            username: u.username ?? null,
            first_name: null,
            last_name: null,
            avatar_url: u.avatar_url ?? null,
          }))
          .filter(u => !selectedUserIds.includes(u.id) && u.id !== user?.id);
        setSearchResults(filtered);
      } catch {
        setSearchResults([]);
      } finally {
        setIsSearching(false);
      }
    }, 300);

    return () => clearTimeout(timeoutId);
  }, [searchTerm, selectedUserIds, user?.id]);

  const handleUserSelect = (picked: SearchResult) => {
    setSelectedUsers(prev => [...prev, picked]);
    setSearchTerm('');
    setSearchResults([]);
  };

  const handleUserRemove = (userId: string) => {
    setSelectedUsers(prev => prev.filter(u => u.id !== userId));
  };

  const handleCreate = useCallback(async () => {
    if (!user?.id || !groupName.trim()) {
      Alert.alert('Group name required', 'Please enter a group name.');
      return;
    }

    setIsCreating(true);
    try {
      const ownerName =
        user.user_metadata?.name || user.user_metadata?.full_name || user.email || 'User';

      const created = await createGroup({
        name: groupName.trim(),
        description: groupDescription.trim() || undefined,
        ownerId: user.id,
        ownerName,
        permissions,
        parentId,
        memberIds: selectedUserIds,
        memberDetails: selectedUsers.map(u => ({
          id: u.id,
          name: u.name || u.username || 'User',
          avatarUrl: u.avatar_url || undefined,
        })),
      });

      navigation.replace('GroupChat', { groupId: created.id, groupName: created.name });
    } catch {
      Alert.alert('Error', 'Failed to create group. Please try again.');
    } finally {
      setIsCreating(false);
    }
  }, [
    user,
    groupName,
    groupDescription,
    permissions,
    selectedUserIds,
    selectedUsers,
    parentId,
    isSubGroup,
    createGroup,
    navigation,
  ]);

  if (step === 'select_members') {
    return (
      <SafeAreaView className="flex-1 bg-slate-50 dark:bg-slate-900" edges={['top']}>
        <ScreenHeader
          title={isSubGroup ? 'New Sub-group' : 'New Group'}
          subtitle={
            isSubGroup
              ? parentName
                ? `Inside "${parentName}"`
                : 'Add members by @username'
              : 'Add members by @username'
          }
          right={
            <Button variant="ghost" size="sm" onPress={() => navigation.goBack()}>
              Cancel
            </Button>
          }
        />

        <ScrollView className="flex-1 px-4" keyboardShouldPersistTaps="handled">
          <View className="flex-row items-center border border-slate-200 dark:border-slate-600 rounded-2xl px-3 bg-white dark:bg-slate-800 mt-2 mb-3">
            <Ionicons name="search" size={18} color="#94a3b8" />
            <TextInput
              value={searchTerm}
              onChangeText={setSearchTerm}
              placeholder="Search by @username or name..."
              placeholderTextColor="#94a3b8"
              autoFocus
              className="flex-1 py-3 px-2 text-slate-900 dark:text-slate-100"
            />
          </View>

          {isSearching ? (
            <ActivityIndicator className="py-6" color="#6366f1" />
          ) : null}

          {!isSearching && searchTerm.length >= 2 && searchResults.length === 0 ? (
            <View className="items-center py-8">
              <Ionicons name="people-outline" size={40} color="#94a3b8" />
              <Text className="text-sm text-slate-500 dark:text-slate-400 mt-2 text-center">
                No users found matching &quot;{searchTerm}&quot;
              </Text>
            </View>
          ) : null}

          {searchResults.map(u => (
            <Pressable
              key={u.id}
              onPress={() => handleUserSelect(u)}
              className="flex-row items-center p-3 mb-2 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 active:opacity-90"
            >
              <Avatar name={u.name} size={40} />
              <View className="flex-1 ml-3 min-w-0">
                <Text className="font-semibold text-slate-900 dark:text-slate-100" numberOfLines={1}>
                  {u.name}
                </Text>
                {u.username ? (
                  <Text className="text-sm text-indigo-600 dark:text-indigo-400">@{u.username}</Text>
                ) : null}
              </View>
              <Ionicons name="add-circle-outline" size={22} color="#6366f1" />
            </Pressable>
          ))}

          {selectedUsers.length > 0 ? (
            <View className="mt-4 p-4 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700">
              <Text className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-3">
                Selected ({selectedUsers.length})
              </Text>
              <View className="flex-row flex-wrap gap-2">
                {selectedUsers.map(u => (
                  <Pressable
                    key={u.id}
                    onPress={() => handleUserRemove(u.id)}
                    className="flex-row items-center bg-indigo-50 dark:bg-indigo-900/40 px-3 py-1.5 rounded-full"
                  >
                    <Text className="text-sm text-indigo-800 dark:text-indigo-200 mr-1">
                      {u.username ? `@${u.username}` : u.name}
                    </Text>
                    <Ionicons name="close" size={14} color="#6366f1" />
                  </Pressable>
                ))}
              </View>
            </View>
          ) : (
            <View className="mt-4 p-4 rounded-2xl bg-indigo-50 dark:bg-indigo-900/30">
              <Text className="font-medium text-indigo-800 dark:text-indigo-200">Invite link after creation</Text>
              <Text className="text-sm text-indigo-600 dark:text-indigo-300 mt-1">
                Share an invite link once the group is created.
              </Text>
            </View>
          )}
        </ScrollView>

        <View className="px-4 pb-4 pt-2 border-t border-slate-100 dark:border-slate-800">
          <Button
            fullWidth
            onPress={() => setStep('group_details')}
            variant={selectedUsers.length > 0 ? 'primary' : 'secondary'}
          >
            {selectedUsers.length > 0 ? 'Next' : 'Skip — create without members'}
          </Button>
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView className="flex-1 bg-slate-50 dark:bg-slate-900" edges={['top']}>
      <ScreenHeader
        title={isSubGroup ? 'Sub-group Details' : 'Group Details'}
        subtitle={
          isSubGroup && parentName
            ? `Inside "${parentName}" · ${selectedUsers.length + 1} members`
            : `${selectedUsers.length + 1} members`
        }
        right={
          <Button variant="ghost" size="sm" onPress={() => setStep('select_members')}>
            Back
          </Button>
        }
      />

      <ScrollView className="flex-1 px-4" keyboardShouldPersistTaps="handled">
        <View className="items-center py-4">
          <View className="w-24 h-24 rounded-full bg-slate-200 dark:bg-slate-700 items-center justify-center mb-4">
            <Ionicons name="people" size={40} color="#94a3b8" />
          </View>
          <TextInput
            value={groupName}
            onChangeText={setGroupName}
            placeholder={isSubGroup ? 'Sub-group name (required)' : 'Group name (required)'}
            placeholderTextColor="#94a3b8"
            className="w-full text-center text-lg font-semibold border-b-2 border-slate-200 dark:border-slate-600 py-2 text-slate-900 dark:text-slate-100 mb-3"
          />
          <TextInput
            value={groupDescription}
            onChangeText={setGroupDescription}
            placeholder="Optional description"
            placeholderTextColor="#94a3b8"
            multiline
            numberOfLines={2}
            className="w-full text-center text-sm border border-slate-200 dark:border-slate-600 rounded-xl px-3 py-2 text-slate-900 dark:text-slate-100 bg-white dark:bg-slate-800"
          />
        </View>

        <View className="p-4 rounded-2xl bg-white dark:bg-slate-800 border border-slate-100 dark:border-slate-700 mb-4">
          <Text className="font-semibold text-slate-800 dark:text-slate-200 mb-2">Member permissions</Text>
          <PermissionToggle
            label="Send messages"
            enabled={permissions.canSendMessages}
            onChange={val => setPermissions(p => ({ ...p, canSendMessages: val }))}
          />
          <PermissionToggle
            label="Add other members"
            enabled={permissions.canAddMembers}
            onChange={val => setPermissions(p => ({ ...p, canAddMembers: val }))}
          />
          <PermissionToggle
            label="Edit group info"
            enabled={permissions.canEditSettings}
            onChange={val => setPermissions(p => ({ ...p, canEditSettings: val }))}
          />
          <PermissionToggle
            label="Approve new members"
            enabled={permissions.canApproveMembers}
            onChange={val => setPermissions(p => ({ ...p, canApproveMembers: val }))}
          />
        </View>
      </ScrollView>

      <View className="px-4 pb-4 pt-2 border-t border-slate-100 dark:border-slate-800">
        <Button fullWidth loading={isCreating} disabled={!groupName.trim()} onPress={handleCreate}>
          {isSubGroup ? 'Create Sub-group' : 'Create Group'}
        </Button>
      </View>
    </SafeAreaView>
  );
}

export default CreateGroupScreen;
