import React, { useState } from 'react';
import {
  Alert,
  KeyboardAvoidingView,
  Platform,
  Pressable,
  ScrollView,
  Text,
  TextInput,
  View,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Ionicons } from '@expo/vector-icons';
import {
  useMarketplaceStore,
  useAuthStore,
  ACADEMIC_CATEGORIES,
  STUDENT_LIFE_CATEGORIES,
  type MarketplaceCategory,
} from '../../stores';
import { Button } from '../../components/ui';

type NavigationProp = {
  goBack: () => void;
  navigate: (screen: string, params?: Record<string, unknown>) => void;
};

const ALL_CATEGORIES = [...ACADEMIC_CATEGORIES, ...STUDENT_LIFE_CATEGORIES];

export function CreateListingScreen({ navigation }: { navigation: NavigationProp }) {
  const { user } = useAuthStore();
  const { createListing, isLoading } = useMarketplaceStore();

  const [title, setTitle] = useState('');
  const [category, setCategory] = useState<MarketplaceCategory>('textbook_exchange');
  const [price, setPrice] = useState('');
  const [description, setDescription] = useState('');
  const [location, setLocation] = useState('');
  const [showCategories, setShowCategories] = useState(false);

  const selectedCategory = ALL_CATEGORIES.find(c => c.id === category);

  const handleSubmit = async () => {
    if (!user?.id) {
      Alert.alert('Sign in required', 'Please sign in to create a listing.');
      return;
    }
    if (!title.trim()) {
      Alert.alert('Missing title', 'Please enter a title for your listing.');
      return;
    }

    const parsedPrice = price.trim() ? parseFloat(price.replace(/,/g, '')) : undefined;
    if (price.trim() && (!parsedPrice || parsedPrice < 0)) {
      Alert.alert('Invalid price', 'Please enter a valid price.');
      return;
    }

    try {
      const listing = await createListing(
        {
          user_id: user.id,
          category,
          title: title.trim(),
          description: description.trim() || undefined,
          price: parsedPrice,
          location: location.trim() || undefined,
          images: [],
          status: 'active',
        },
        user.id
      );
      Alert.alert('Listing created', 'Your listing is now live.');
      navigation.navigate('ListingDetail', { listingId: listing.id });
    } catch {
      Alert.alert('Error', 'Failed to create listing. Please try again.');
    }
  };

  return (
    <SafeAreaView className="flex-1 bg-slate-50 dark:bg-slate-900" edges={['top']}>
      <KeyboardAvoidingView
        className="flex-1"
        behavior={Platform.OS === 'ios' ? 'padding' : undefined}
      >
        <View className="px-4 pt-2 pb-3 flex-row items-center">
          <Pressable onPress={() => navigation.goBack()} className="p-2 -ml-2 mr-1">
            <Ionicons name="arrow-back" size={22} color="#64748b" />
          </Pressable>
          <Text className="text-xl font-bold text-slate-900 dark:text-slate-100">Create Listing</Text>
        </View>

        <ScrollView className="flex-1 px-4" contentContainerStyle={{ paddingBottom: 32 }}>
          <Text className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Title *</Text>
          <TextInput
            value={title}
            onChangeText={setTitle}
            placeholder="What are you selling?"
            placeholderTextColor="#94a3b8"
            className="p-3 rounded-xl border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 mb-4"
          />

          <Text className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Category *</Text>
          <Pressable
            onPress={() => setShowCategories(v => !v)}
            className="p-3 rounded-xl border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-800 mb-2 flex-row items-center justify-between"
          >
            <Text className="text-slate-900 dark:text-slate-100">{selectedCategory?.name ?? 'Select category'}</Text>
            <Ionicons name={showCategories ? 'chevron-up' : 'chevron-down'} size={18} color="#64748b" />
          </Pressable>
          {showCategories ? (
            <View className="flex-row flex-wrap gap-2 mb-4">
              {ALL_CATEGORIES.map(cat => (
                <Pressable
                  key={cat.id}
                  onPress={() => {
                    setCategory(cat.id);
                    setShowCategories(false);
                  }}
                  className={`px-3 py-1.5 rounded-full border ${
                    category === cat.id
                      ? 'bg-indigo-600 border-indigo-600'
                      : 'bg-white dark:bg-slate-800 border-slate-200 dark:border-slate-600'
                  }`}
                >
                  <Text
                    className={`text-xs font-medium ${
                      category === cat.id ? 'text-white' : 'text-slate-600 dark:text-slate-300'
                    }`}
                  >
                    {cat.name}
                  </Text>
                </Pressable>
              ))}
            </View>
          ) : (
            <View className="mb-4" />
          )}

          <Text className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Price (₦)</Text>
          <TextInput
            value={price}
            onChangeText={setPrice}
            placeholder="Leave empty for free"
            placeholderTextColor="#94a3b8"
            keyboardType="numeric"
            className="p-3 rounded-xl border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 mb-4"
          />

          <Text className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Location</Text>
          <TextInput
            value={location}
            onChangeText={setLocation}
            placeholder="Campus or city"
            placeholderTextColor="#94a3b8"
            className="p-3 rounded-xl border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 mb-4"
          />

          <Text className="text-sm font-semibold text-slate-700 dark:text-slate-300 mb-2">Description</Text>
          <TextInput
            value={description}
            onChangeText={setDescription}
            placeholder="Describe your item, condition, pickup details…"
            placeholderTextColor="#94a3b8"
            multiline
            numberOfLines={5}
            textAlignVertical="top"
            className="min-h-[120px] p-3 rounded-xl border border-slate-200 dark:border-slate-600 bg-white dark:bg-slate-800 text-slate-900 dark:text-slate-100 mb-6"
          />

          <Button fullWidth loading={isLoading} onPress={handleSubmit}>
            Publish Listing
          </Button>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}
